{v:'VER',what:'the What is new card is a left-aligned header over a rule, a 900px card on a scrim, with a Got it button (critic: no scrim, 1560px slab, no close or primary, centred amber title; screen 40)',
 run:function(){
   if(typeof drawHubHUD!=='function'||!window.__hubEnter||!window.__wnseen||!window.__P) return 'SKIP: no floor here';
   var bad=[], texts=[], rects=[], oT=null, oR=null, p0=null, runs0=0, hadT=false, hadR=false;
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __hubEnter(); p0=__P(); runs0=p0.runs; p0.runs=Math.max(1,runs0|0); __wnseen(0);
     hadT=Object.prototype.hasOwnProperty.call(ctx,'fillText'); hadR=Object.prototype.hasOwnProperty.call(ctx,'fillRect');
     oT=ctx.fillText; oR=ctx.fillRect;
     ctx.fillText=function(t,x,y){ texts.push({t:String(t),x:x,y:y,al:ctx.textAlign}); return oT.apply(ctx,arguments); };
     ctx.fillRect=function(x,y,w,h){ rects.push({x:x,y:y,w:w,h:h,fs:String(ctx.fillStyle)}); return oR.apply(ctx,arguments); };
     try{ drawHubHUD(0,0); }catch(e){ bad.push('draw threw: '+(e&&e.message||e)); }
   } finally {
     try{ if(hadT) ctx.fillText=oT; else delete ctx.fillText; if(hadR) ctx.fillRect=oR; else delete ctx.fillRect; }catch(_r){}
     try{ if(p0) p0.runs=runs0; __wnseen(1); __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
   }
   var ti=null, row=null, btn=false, rule=null, scrim=false, i;
   for(i=0;i<texts.length;i++){ if(!ti&&/new in/i.test(texts[i].t)) ti=texts[i]; if(!row&&/^1\. /.test(texts[i].t)) row=texts[i]; if(texts[i].t==='Got it') btn=true; }
   if(!ti) return 'the card did not draw';
   for(i=0;i<rects.length;i++){ if(rects[i].h===1&&rects[i].w>LH(300)&&rects[i].w<=LH(620)+1&&Math.abs(rects[i].y-ti.y)<LH(25)) rule=rects[i]; if(/^rgba\(6, 7, 8, 0\.8/.test(rects[i].fs)&&rects[i].w>=W/Math.max(1,hudRes())-1) scrim=true; }
   if(ti.al!=='left') bad.push('the title is '+ti.al+' aligned, not left');
   if(row&&Math.abs(row.x-ti.x)>1) bad.push('the title and the notes do not share a left edge');
   if(!rule) bad.push('no header rule under the title');
   if(!scrim) bad.push('no scrim behind the card');
   if(!btn) bad.push('no Got it button');
   return bad.length?bad.join('; '):null;
 }},
